<#
=====================================================================
 ABFverify - Gift Sending feature installer  (v4 - gift sizes)
 --------------------------------------------------------------------
 WHAT IT DOES
   1. Creates the "gifts" Django app (models, views, admin, services,
      urls, context processor, migrations 0001-0003).
   2. Adds the customer pages: Send a Gift (search + categories,
      gift note, compressed photos) + My Gift Orders.
   3. Adds the finance-side Gift Orders page + glowing bell on all
      finance pages; tracking accepts a number, link or any text.
   4. NEW: creates the "siteconfig" app - upload the site logo once in
      the admin (Site Settings) and every template serves it from
      Cloudinary CDN instead of the slow static file.
   5. NEW: replaces the /semilore/ admin landing page with a custom
      branded ABFverify control center (templates/admin/index.html) -
      the default Django design is no longer shown.
   6. NEW: finance dashboard records gift purchases too - gift revenue
      is included in totals/records and gets its own Gifts channel card.
   7. NEW: size options per gift group - admin tick-boxes (shoe, cloth,
      frame, ring) make the customer pick a size on the order form, and
      the chosen size shows on the order (migration 0004).
   8. Patches settings.py, config/urls.py, finance/views.py,
      finance/urls.py, finance/services.py, finance.css,
      dashboard_base.html, the 4 finance templates and every template
      that references the old static logo (.bak-gifts backups kept).
   9. Runs migrations + collectstatic.

 HOW TO RUN (from the project root, next to manage.py):
   powershell -ExecutionPolicy Bypass -File .\install_gifts.ps1
=====================================================================
#>

$ErrorActionPreference = "Stop"

# ---------- locate project root ----------
$root = Get-Location
if (-not (Test-Path (Join-Path $root "manage.py"))) {
    Write-Host "ERROR: manage.py not found." -ForegroundColor Red
    Write-Host "cd into your project root (next to manage.py) and run again." -ForegroundColor Yellow
    exit 1
}
Write-Host "Project root: $root" -ForegroundColor Cyan
Write-Host "INSTALLER VERSION: v4 (gift sizes)" -ForegroundColor Magenta

function Read-Utf8([string]$path) {
    return [IO.File]::ReadAllText($path, (New-Object Text.UTF8Encoding($false)))
}
function Write-Utf8([string]$path, [string]$content) {
    [IO.File]::WriteAllText($path, $content, (New-Object Text.UTF8Encoding($false)))
}
function Backup-Once([string]$path) {
    $bak = "$path.bak-gifts"
    if ((Test-Path $path) -and -not (Test-Path $bak)) {
        Copy-Item $path $bak
        Write-Host "  backup -> $bak" -ForegroundColor DarkGray
    }
}
function Write-B64File([string]$rel, [string]$b64) {
    $dest = Join-Path $root $rel
    $dir = Split-Path $dest -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
    [IO.File]::WriteAllBytes($dest, [Convert]::FromBase64String($b64))
    Write-Host "  wrote $rel" -ForegroundColor DarkGray
}
function Decode([string]$b64) {
    return [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64))
}

