# ---------- 2) patch config/settings.py ----------
Write-Host "`n[2/10] Patching config/settings.py..." -ForegroundColor Green
$settingsPath = Join-Path $root "config\settings.py"
Backup-Once $settingsPath
$s = Read-Utf8 $settingsPath

if ($s -notmatch '"gifts",') {
    $anchor = '    "referrals",'
    if ($s.Contains($anchor)) {
        $s = $s.Replace($anchor, $anchor + "`r`n" + '    "gifts",')
        Write-Host "  added gifts to INSTALLED_APPS" -ForegroundColor DarkGray
    } else {
        Write-Host "  WARNING: could not find `"referrals`", in INSTALLED_APPS - add `"gifts`", manually." -ForegroundColor Yellow
    }
} else {
    Write-Host "  INSTALLED_APPS already patched, skipping" -ForegroundColor DarkGray
}

if ($s -notmatch 'gifts\.context_processors\.pending_gift_orders') {
    $cpAnchor = '"wallet.context_processors.wallet_balance",'
    if ($s.Contains($cpAnchor)) {
        $s = $s.Replace($cpAnchor, $cpAnchor + "`r`n" + '                "gifts.context_processors.pending_gift_orders",')
        Write-Host "  added gift orders context processor" -ForegroundColor DarkGray
    } else {
        Write-Host "  WARNING: wallet context processor line not found - add gifts.context_processors.pending_gift_orders manually." -ForegroundColor Yellow
    }
} else {
    Write-Host "  context processor already patched, skipping" -ForegroundColor DarkGray
}

if ($s -notmatch '"siteconfig",') {
    $giftsAppLine = '    "gifts",'
    $refAppLine = '    "referrals",'
    if ($s.Contains($giftsAppLine)) {
        $s = $s.Replace($giftsAppLine, $giftsAppLine + "`r`n" + '    "siteconfig",')
        Write-Host "  added siteconfig to INSTALLED_APPS" -ForegroundColor DarkGray
    } elseif ($s.Contains($refAppLine)) {
        $s = $s.Replace($refAppLine, $refAppLine + "`r`n" + '    "siteconfig",')
        Write-Host "  added siteconfig to INSTALLED_APPS" -ForegroundColor DarkGray
    } else {
        Write-Host "  WARNING: INSTALLED_APPS anchor not found - add `"siteconfig`", manually." -ForegroundColor Yellow
    }
} else {
    Write-Host "  siteconfig already in INSTALLED_APPS, skipping" -ForegroundColor DarkGray
}

if ($s -notmatch 'siteconfig\.context_processors') {
    $scCp = '                "siteconfig.context_processors.site_settings",' + "`r`n" + '                "siteconfig.context_processors.admin_home_stats",'
    $giftCpLine = '                "gifts.context_processors.pending_gift_orders",'
    $walletCpLine = '"wallet.context_processors.wallet_balance",'
    if ($s.Contains($giftCpLine)) {
        $s = $s.Replace($giftCpLine, $giftCpLine + "`r`n" + $scCp)
        Write-Host "  added siteconfig context processors" -ForegroundColor DarkGray
    } elseif ($s.Contains($walletCpLine)) {
        $s = $s.Replace($walletCpLine, $walletCpLine + "`r`n" + $scCp)
        Write-Host "  added siteconfig context processors" -ForegroundColor DarkGray
    } else {
        Write-Host "  WARNING: context processor anchor not found - add siteconfig context processors manually." -ForegroundColor Yellow
    }
} else {
    Write-Host "  siteconfig context processors already present, skipping" -ForegroundColor DarkGray
}
Write-Utf8 $settingsPath $s

# ---------- 3) patch config/urls.py ----------
Write-Host "`n[3/10] Patching config/urls.py..." -ForegroundColor Green
$urlsPath = Join-Path $root "config\urls.py"
Backup-Once $urlsPath
$u = Read-Utf8 $urlsPath
if ($u -notmatch 'include\("gifts\.urls"\)') {
    $anchor = '    path("", include("marketplace.urls")),'
    if ($u.Contains($anchor)) {
        $u = $u.Replace($anchor, $anchor + "`r`n`r`n    path(`"`", include(`"gifts.urls`")),")
        Write-Host "  added gifts urls" -ForegroundColor DarkGray
    } else {
        Write-Host "  WARNING: marketplace include not found - add path(`"`", include(`"gifts.urls`")) manually." -ForegroundColor Yellow
    }
} else {
    Write-Host "  urls already patched, skipping" -ForegroundColor DarkGray
}
Write-Utf8 $urlsPath $u

# ---------- 4) patch finance/views.py + finance/urls.py ----------
Write-Host "`n[4/10] Patching finance views and urls..." -ForegroundColor Green
$fviewsPath = Join-Path $root "finance\views.py"
Backup-Once $fviewsPath
$fv = Read-Utf8 $fviewsPath
if ($fv -notmatch 'def gift_orders\(') {
    if (-not $fv.EndsWith("`n")) { $fv += "`r`n" }
    $fv += (Decode $VIEWS_APPEND_B64).Replace("`n", "`r`n")
    Write-Utf8 $fviewsPath $fv
    Write-Host "  appended gift_orders + gift_order_update views" -ForegroundColor DarkGray
} else {
    Write-Host "  finance views already present - replacing with the updated version" -ForegroundColor DarkGray
    $marker = $fv.IndexOf("# Gift orders (gifts app)")
    if ($marker -ge 0) {
        $dashes = $fv.LastIndexOf("# ----", $marker)
        if ($dashes -ge 0) {
            $fv = $fv.Substring(0, $dashes).TrimEnd() + "`r`n"
            $fv += (Decode $VIEWS_APPEND_B64).Replace("`n", "`r`n")
            Write-Utf8 $fviewsPath $fv
            Write-Host "  gift order views refreshed" -ForegroundColor DarkGray
        }
    }
}

$furlsPath = Join-Path $root "finance\urls.py"
Backup-Once $furlsPath
$fu = Read-Utf8 $furlsPath
if ($fu -notmatch 'finance_gift_orders') {
    $restockLine = '    path("record-restock/", views.record_untracked_restock, name="record_untracked_restock"),'
    if ($fu.Contains($restockLine)) {
        $fu = $fu.Replace($restockLine, (Decode $URLS_INSERT_B64).Replace("`n", "`r`n"))
        Write-Utf8 $furlsPath $fu
        Write-Host "  added gift order routes" -ForegroundColor DarkGray
    } else {
        Write-Host "  WARNING: record-restock route not found - add the gift-orders routes to finance/urls.py manually." -ForegroundColor Yellow
    }
} else {
    Write-Host "  finance urls already patched, skipping" -ForegroundColor DarkGray
}

# ---------- 5) append finance.css ----------
Write-Host "`n[5/10] Appending gift styles to static/css/finance.css..." -ForegroundColor Green
$fcssPath = Join-Path $root "static\css\finance.css"
Backup-Once $fcssPath
$fc = Read-Utf8 $fcssPath
if ($fc -notmatch 'gift-bell') {
    if (-not $fc.EndsWith("`n")) { $fc += "`r`n" }
    $fc += (Decode $CSS_APPEND_B64).Replace("`n", "`r`n")
    Write-Utf8 $fcssPath $fc
    Write-Host "  appended bell + gift orders styles" -ForegroundColor DarkGray
} else {
    Write-Host "  finance.css already patched - replacing old gift block with the new one" -ForegroundColor DarkGray
    $marker = "Gift Orders - bell + orders page"
    $idx = $fc.IndexOf("Gift Orders")
    if ($idx -ge 0) {
        # cut the previously appended block (starts at its comment banner) and re-append fresh
        $bannerIdx = $fc.LastIndexOf("/* ====", $idx)
        if ($bannerIdx -ge 0) { $fc = $fc.Substring(0, $bannerIdx).TrimEnd() + "`r`n" }
        $fc += (Decode $CSS_APPEND_B64).Replace("`n", "`r`n")
        Write-Utf8 $fcssPath $fc
        Write-Host "  gift styles refreshed" -ForegroundColor DarkGray
    }
}

# ---------- 6) patch dashboard_base.html sidebar + finance page bells ----------
Write-Host "`n[6/10] Patching sidebar and finance page bells..." -ForegroundColor Green
$basePath = Join-Path $root "templates\panel\dashboard_base.html"
Backup-Once $basePath
$bt = Read-Utf8 $basePath
if ($bt -notmatch 'fa-gifts') {
    $rocketIdx = $bt.IndexOf('fa-rocket')
    if ($rocketIdx -ge 0) {
        $closeIdx = $bt.IndexOf('</button>', $rocketIdx)
        if ($closeIdx -ge 0) {
            $insertAt = $closeIdx + '</button>'.Length
            $sidebar = (Decode $SIDEBAR_B64).Replace("`n", "`r`n")
            $bt = $bt.Substring(0, $insertAt) + $sidebar + $bt.Substring($insertAt)
            Write-Utf8 $basePath $bt
            Write-Host "  added Send Gift + My Gift Orders to sidebar" -ForegroundColor DarkGray
        } else {
            Write-Host "  WARNING: closing </button> after Boost not found." -ForegroundColor Yellow
        }
    } else {
        Write-Host "  WARNING: Boost Accounts button not found - add the sidebar buttons manually." -ForegroundColor Yellow
    }
} else {
    Write-Host "  sidebar already patched, skipping" -ForegroundColor DarkGray
}

$financeTemplates = @(
    "templates\finance\dashboard.html",
    "templates\finance\analytics.html",
    "templates\finance\inventory.html",
    "templates\finance\rewards.html"
)
$bellLine = (Decode $BELL_INCLUDE_B64).Replace("`n", "`r`n")
foreach ($rel in $financeTemplates) {
    $p = Join-Path $root $rel
    if (-not (Test-Path $p)) {
        Write-Host "  WARNING: $rel not found, skipping" -ForegroundColor Yellow
        continue
    }
    Backup-Once $p
    $c = Read-Utf8 $p
    if ($c -notmatch 'gift_bell\.html') {
        $ha = '<div class="header-actions">'
        if ($c.Contains($ha)) {
            $c = $c.Replace($ha, $bellLine)
            Write-Utf8 $p $c
            Write-Host "  bell added to $rel" -ForegroundColor DarkGray
        } else {
            Write-Host "  WARNING: header-actions not found in $rel" -ForegroundColor Yellow
        }
    } else {
        Write-Host "  $rel already has the bell, skipping" -ForegroundColor DarkGray
    }
}


# ---------- 7) record gift sales in finance/services.py ----------
Write-Host "`n[7/10] Recording gift sales in finance totals..." -ForegroundColor Green
$svcPath = Join-Path $root "finance\services.py"
if (Test-Path $svcPath) {
    Backup-Once $svcPath
    $svc = (Read-Utf8 $svcPath).Replace("`r`n", "`n")
    if ($svc -match 'gift_revenue') {
        Write-Host "  gift revenue already recorded, skipping" -ForegroundColor DarkGray
    } else {
        $pairs = @(
            @((Decode $SVC_A1_B64), (Decode $SVC_R1_B64)),
            @((Decode $SVC_A2_B64), (Decode $SVC_R2_B64)),
            @((Decode $SVC_A3_B64), (Decode $SVC_R3_B64))
        )
        $svcOk = $true
        foreach ($p in $pairs) {
            if ($svc.Contains($p[0])) {
                $svc = $svc.Replace($p[0], $p[1])
            } else {
                $svcOk = $false
            }
        }
        if ($svcOk) {
            Write-Utf8 $svcPath $svc
            Write-Host "  gift revenue added to finance totals + channels" -ForegroundColor DarkGray
        } else {
            Write-Host "  WARNING: finance/services.py anchors not found - gift revenue patch skipped." -ForegroundColor Yellow
        }
    }
} else {
    Write-Host "  WARNING: finance\services.py not found - skipping." -ForegroundColor Yellow
}

# ---------- 8) add the Gifts channel card to the finance dashboard ----------
Write-Host "`n[8/10] Adding the Gifts card to the finance dashboard..." -ForegroundColor Green
$dashPath = Join-Path $root "templates\finance\dashboard.html"
if (Test-Path $dashPath) {
    Backup-Once $dashPath
    $dash = (Read-Utf8 $dashPath).Replace("`r`n", "`n")
    if ($dash -match 'Gift Sales') {
        Write-Host "  Gifts card already present, skipping" -ForegroundColor DarkGray
    } else {
        $da = Decode $DASH_A_B64
        $dr = Decode $DASH_R_B64
        if ($dash.Contains($da)) {
            $dash = $dash.Replace($da, $dr)
            Write-Utf8 $dashPath $dash
            Write-Host "  Gifts channel card added after Boost Sales" -ForegroundColor DarkGray
        } else {
            Write-Host "  WARNING: Boost Sales card anchor not found - add the Gifts card manually." -ForegroundColor Yellow
        }
    }
} else {
    Write-Host "  WARNING: templates\finance\dashboard.html not found - skipping." -ForegroundColor Yellow
}

# ---------- 9) use the uploaded logo in every template ----------
Write-Host "`n[9/10] Switching templates to the uploaded logo..." -ForegroundColor Green
$logoOld1 = "{% static 'images/mylogo1.png' %}"
$logoOld2 = "{% static 'images/mylogo1.png'%}"
$logoNew = "{% if site_settings.logo %}{{ site_settings.logo.url }}{% else %}{% static 'images/mylogo1.png' %}{% endif %}"
$tplFiles = Get-ChildItem -Path (Join-Path $root "templates") -Recurse -Filter *.html
$logoCount = 0
foreach ($f in $tplFiles) {
    $c = Read-Utf8 $f.FullName
    if ($c.Contains("site_settings.logo")) { continue }
    if ($c.Contains($logoOld1) -or $c.Contains($logoOld2)) {
        Backup-Once $f.FullName
        $c = $c.Replace($logoOld1, $logoNew).Replace($logoOld2, $logoNew)
        Write-Utf8 $f.FullName $c
        $logoCount++
        Write-Host "  logo hook -> $($f.Name)" -ForegroundColor DarkGray
    }
}
Write-Host "  $logoCount template(s) updated to use the uploaded logo" -ForegroundColor DarkGray

# ---------- 10) Django: check + migrate + collectstatic ----------
Write-Host "`n[10/10] Running Django checks and migrations..." -ForegroundColor Green

$py = "python"
try { & $py --version | Out-Null } catch {
    Write-Host "WARNING: 'python' not found on PATH - run these manually:" -ForegroundColor Yellow
    Write-Host "  python manage.py migrate" -ForegroundColor Yellow
    Write-Host "  python manage.py collectstatic --noinput" -ForegroundColor Yellow
    $py = $null
}

if ($py) {
    & $py manage.py check
    if ($LASTEXITCODE -ne 0) {
        Write-Host "ERROR: 'manage.py check' failed - fix the error above, then run migrate." -ForegroundColor Red
        exit 1
    }
    & $py manage.py migrate
    if ($LASTEXITCODE -ne 0) {
        Write-Host "ERROR: migrations failed - see the message above." -ForegroundColor Red
        exit 1
    }
    & $py manage.py collectstatic --noinput
    if ($LASTEXITCODE -ne 0) {
        Write-Host "NOTE: collectstatic failed locally - not fatal. Run it on your server during deploy." -ForegroundColor Yellow
    }
}

Write-Host ""
Write-Host "==================================================================" -ForegroundColor Green
Write-Host " GIFTS + ADMIN CONTROL CENTER INSTALLED / UPDATED SUCCESSFULLY" -ForegroundColor Green
Write-Host "==================================================================" -ForegroundColor Green
